const fmtDeadline = (d, t) => {
  if (!d) return "Belum diatur";
  const p = d.split("-");
  return `${Number(p[2])} ${BULAN[Number(p[1]) - 1]} ${p[0]}${t ? ", " + t : ""}`;
};
const hitungAkhir = (...v) => {
  const vals = v.filter((x) => x !== "" && x !== null && !isNaN(x)).map(Number);
  return vals.length ? Math.round(vals.reduce((a, b) => a + b, 0) / vals.length) : "-";
};
const loadStore = () => {
  try { return JSON.parse(localStorage.getItem(STORE_KEY)) || {}; } catch (e) { return {}; }
};
const pickArr = (v, fallback) => (Array.isArray(v) ? v : fallback);

const PILL = { Sudah: "pill-tosca", Belum: "pill-coral", PDF: "pill-blue", Catatan: "pill-amber" };
const Pill = ({ s }) => <span className={"pill " + (PILL[s] || "pill-tosca")}>{s}</span>;

const svgProps = { width: 14, height: 14, viewBox: "0 0 24 24", fill: "none", stroke: "currentColor", strokeWidth: 2, strokeLinecap: "round", strokeLinejoin: "round" };
const EditBtn = ({ onClick }) => (
  <div className="icon-btn" onClick={onClick} title="Edit">
    <svg {...svgProps}><path d="M12 20h9" /><path d="M16.5 3.5a2.12 2.12 0 0 1 3 3L7 19l-4 1 1-4Z" /></svg>
  </div>
);
const TrashBtn = ({ onClick, title = "Hapus" }) => (
  <div className="icon-btn danger" onClick={onClick} title={title}>
    <svg {...svgProps}><path d="M3 6h18" /><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2" /><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" /></svg>
  </div>
);
const Opts = ({ list }) => list.map((o) => <option key={o}>{o}</option>);
const EmptyRow = ({ cols, text }) => (
  <tr><td colSpan={cols} style={{ textAlign: "center", color: "var(--ink-faint)" }}>{text}</td></tr>
);
const Modal = ({ open, onClose, small, style, children }) => (
  <div className={"modal-overlay" + (open ? " open" : "")} onClick={(e) => e.target === e.currentTarget && onClose()}>
    <div className={"modal" + (small ? " small" : "")} style={style}>{children}</div>
  </div>
);
const Err = ({ msg }) => msg ? <p style={{ color: "var(--coral)", fontSize: 12.5, margin: "0 0 10px" }}>{msg}</p> : null;
const PageHead = ({ title, sub, btn, onBtn }) => (
  <div className="panel-head" style={{ border: "none", padding: "0 0 14px" }}>
    <div><p className="page-title" style={{ margin: 0 }}>{title}</p><p className="page-sub" style={{ margin: "2px 0 0" }}>{sub}</p></div>
    <button className="btn btn-primary" onClick={onBtn}>{btn}</button>
  </div>
);

const blankSoal = (id) => ({ id, tipe: "pg", poin: 10, tanya: "", opsi: ["", "", "", ""], benar: -1 });

export default function PreviewGuru() {
  const stored = loadStore();
  const [sec, setSec] = useState("beranda");
  const [materi, setMateri] = useState(() => pickArr(stored.materiData, initMateri));
  const [assessment, setAssessment] = useState(() => pickArr(stored.assessmentData, initAssessment));
  const [tugas, setTugas] = useState(() => pickArr(stored.tugasData, initTugas));
  const [nilai, setNilai] = useState(() => siswaKelas.map((s) => ({ ...s, tugas: "", kuis: "", uh: "" })));
  const [filterTugas, setFilterTugas] = useState("");
  const [toast, setToast] = useState("");
  const [modal, setModal] = useState(null); // materi | tugas | assessment | confirm | logout
  const [del, setDel] = useState(null);
  const [loggedOut, setLoggedOut] = useState(false);

  const [mEdit, setMEdit] = useState(null);
  const [mForm, setMForm] = useState({});
  const [tEdit, setTEdit] = useState(null);
  const [tForm, setTForm] = useState({});
  const [tErr, setTErr] = useState("");
  const [aEdit, setAEdit] = useState(null);
  const [aForm, setAForm] = useState({});
  const [soalList, setSoalList] = useState([]);
  const [aErr, setAErr] = useState("");

  useEffect(() => {
    try { localStorage.setItem(STORE_KEY, JSON.stringify({ materiData: materi, assessmentData: assessment, tugasData: tugas })); } catch (e) {}
  }, [materi, assessment, tugas]);

  const showToast = (msg) => { setToast(msg); setTimeout(() => setToast(""), 2200); };
  const close = () => setModal(null);
  const activeFilter = tugas.some((t) => t.judul === filterTugas) ? filterTugas : tugas[0]?.judul || "";

  /* ---------- Materi ---------- */
  const blankMateri = { judul: "", mapel: MAPEL[0], kelas: KELAS[0], catatan: "" };
  const openMateri = () => { setMEdit(null); setMForm(blankMateri); setTErr(""); setModal("materi"); };
  const editMateri = (i) => { setMEdit(i); setMForm({ ...blankMateri, ...materi[i] }); setTErr(""); setModal("materi"); };
  const saveMateri = () => {
    if (!mForm.judul.trim()) { setTErr("Judul materi wajib diisi."); return; }
    const data = { judul: mForm.judul.trim(), mapel: mForm.mapel, kelas: mForm.kelas, tanggal: "Baru saja" };
    if (mEdit !== null) setMateri(materi.map((m, i) => (i === mEdit ? { ...m, ...data, tanggal: m.tanggal } : m)));
    else setMateri([data, ...materi]);
    close(); showToast("Materi berhasil disimpan.");
  };

  /* ---------- Tugas ---------- */
  const blankTugas = { judul: "", mapel: MAPEL[0], kelas: KELAS[0], jenis: "pdf", deadlineDate: "", deadlineTime: "23:59", catatan: "", fileName: "" };
  const openTugas = () => { setTEdit(null); setTForm(blankTugas); setTErr(""); setModal("tugas"); };
  const editTugas = (i) => {
    const t = tugas[i];
    setTEdit(i); setTErr("");
    setTForm({ ...blankTugas, ...t, jenis: t.jenis === "PDF" ? "pdf" : "catatan", deadlineTime: t.deadlineTime || "23:59" });
    setModal("tugas");
  };
  const saveTugas = () => {
    if (!tForm.judul.trim()) { setTErr("Judul tugas wajib diisi."); return; }
    if (!tForm.deadlineDate) { setTErr("Batas pengumpulan wajib diisi."); return; }
    const isPdf = tForm.jenis === "pdf";
    const data = {
      judul: tForm.judul.trim(), mapel: tForm.mapel, kelas: tForm.kelas, jenis: isPdf ? "PDF" : "Catatan",
      deadlineDate: tForm.deadlineDate, deadlineTime: tForm.deadlineTime || "",
      catatan: isPdf ? "" : (tForm.catatan || "").trim(), fileName: isPdf ? tForm.fileName || "" : "",
    };
    if (tEdit !== null) setTugas(tugas.map((t, i) => (i === tEdit ? data : t)));
    else setTugas([data, ...tugas]);
    close(); showToast("Tugas berhasil disimpan.");
  };

  /* ---------- Assessment ---------- */
  const blankAssessment = { judul: "", mapel: MAPEL[0], kelas: KELAS[0], tipe: "Kuis", durasi: "", deadlineDate: "" };
  const nextId = (list) => list.reduce((mx, s) => Math.max(mx, s.id), 0) + 1;
  const openAssessment = () => { setAEdit(null); setAForm(blankAssessment); setSoalList([blankSoal(1)]); setAErr(""); setModal("assessment"); };
  const editAssessment = (i) => {
    const a = assessment[i];
    setAEdit(i); setAErr("");
    setAForm({ judul: a.judul, mapel: a.mapel, kelas: a.kelas, tipe: a.tipe, durasi: a.durasi || "", deadlineDate: a.deadlineDate || "" });
    const list = (a.soal || []).map((s, k) => ({ ...s, id: k + 1, opsi: s.tipe === "pg" ? [...s.opsi, "", "", "", ""].slice(0, 4) : ["", "", "", ""] }));
    setSoalList(list.length ? list : [blankSoal(1)]);
    setModal("assessment");
  };
  const setSoal = (id, patch) => setSoalList(soalList.map((s) => (s.id === id ? { ...s, ...patch } : s)));
  const setOpsi = (id, k, v) => setSoalList(soalList.map((s) => (s.id === id ? { ...s, opsi: s.opsi.map((o, n) => (n === k ? v : o)) } : s)));
  const saveAssessment = () => {
    if (!aForm.judul.trim()) return setAErr("Judul assessment wajib diisi.");
    const durasi = Number(aForm.durasi);
    if (!durasi || durasi < 1) return setAErr("Waktu pengerjaan wajib diisi (minimal 1 menit).");
    if (!soalList.length) return setAErr("Tambahkan minimal 1 soal.");
    for (let n = 0; n < soalList.length; n++) {
      const s = soalList[n];
      if (!s.tanya.trim()) return setAErr(`Pertanyaan soal ${n + 1} belum diisi.`);
      if (s.tipe === "pg") {
        if (s.opsi.filter((o) => o.trim()).length < 2) return setAErr(`Soal ${n + 1} minimal punya 2 opsi jawaban.`);
        if (s.benar < 0 || !s.opsi[s.benar].trim()) return setAErr(`Pilih jawaban yang benar untuk soal ${n + 1}.`);
      }
    }
    const soal = soalList.map((s) => ({
      tipe: s.tipe, poin: Number(s.poin) || 0, tanya: s.tanya.trim(),
      opsi: s.tipe === "pg" ? s.opsi.map((o) => o.trim()) : [], benar: s.tipe === "pg" ? s.benar : -1,
    }));
    const data = {
      judul: aForm.judul.trim(), mapel: aForm.mapel, kelas: aForm.kelas, tipe: aForm.tipe,
      jumlahSoal: soal.length, totalPoin: soal.reduce((sum, s) => sum + s.poin, 0), durasi: Math.round(durasi),
      deadlineDate: aForm.deadlineDate, deadlineTime: "", soal,
    };
    if (aEdit !== null) setAssessment(assessment.map((a, i) => (i === aEdit ? data : a)));
    else setAssessment([data, ...assessment]);
    close(); showToast("Assessment berhasil disimpan.");
  };

  /* ---------- Hapus & Nilai ---------- */
  const askDelete = (type, index) => { setDel({ type, index }); setModal("confirm"); };
  const confirmDelete = () => {
    const rm = (arr) => arr.filter((_, i) => i !== del.index);
    if (del.type === "materi") setMateri(rm(materi));
    if (del.type === "assessment") setAssessment(rm(assessment));
    if (del.type === "tugas") setTugas(rm(tugas));
    close(); showToast("Data berhasil dihapus.");
  };
  const updateNilai = (i, field, val) => setNilai(nilai.map((n, k) => (k === i ? { ...n, [field]: val } : n)));

  if (loggedOut) {
    return (
      <div style={{ minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", background: "#0D9488", color: "#fff", fontFamily: "'Plus Jakarta Sans',sans-serif", fontSize: 15 }}>
        Kamu sudah logout - di project asli ini akan redirect ke halaman login.
      </div>
    );
  }

  const waktuKumpul = statusKumpul[activeFilter] || [];

  return (
    <>
      <style>{CSS}</style>
      <div className="app">
        <aside className="sidebar">
          <nav className="menu">
            {NAV.map(([key, label]) => (
              <button key={key} className={"nav-item" + (sec === key ? " active" : "")} onClick={() => setSec(key)}>
                <span className="label">{label}</span>
              </button>
            ))}
            <div className="nav-divider" />
            <button className="nav-item nav-item-danger" onClick={() => setModal("logout")}>
              <span className="ic">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" /><polyline points="16 17 21 12 16 7" /><line x1="21" y1="12" x2="9" y2="12" /></svg>
              </span>
              <span className="label">Logout</span>
            </button>
          </nav>
          <div className="profile-mini" onClick={() => setSec("profil")}>
            <div className="avatar-sm">PB</div>
            <div><div className="pm-name">Budiono</div><div className="pm-role">Guru</div></div>
          </div>
        </aside>

        <div className="main">
          <div className="topbar">
            <div className="topbar-brand"><img src={LOGO} alt="Logo" />LMS SMK CITRA NEGARA</div>
            <div className="topbar-user">
              <div className="name">Pak Budiono, S.Pd.</div>
              <div className="avatar-user">PB</div>
            </div>
          </div>

          <div className="content">
            {sec === "beranda" && (
              <section className="section active">
                <p className="greeting">Selamat datang Pak Budiono, S.Pd.!!</p>
                <div className="quick-cards">
                  <button className="quick-card" onClick={openMateri}><span className="qi">M</span>Buat Materi</button>
                  <button className="quick-card" onClick={openTugas}><span className="qi">T</span>Buat Tugas</button>
                  <button className="quick-card" onClick={openAssessment}><span className="qi">A</span>Buat Assessment</button>
                </div>
                <div className="panel">
                  <div className="panel-head">
                    <h2>Aktivitas terbaru</h2>
                    <span className="link" onClick={() => setSec("pengumuman")}>Lihat semua</span>
                  </div>
                  <div className="panel-body">
                    {activity.map((a) => (
                      <div className="list-row" key={a.t}><div><div className="title">{a.t}</div><div className="sub">{a.m}</div></div></div>
                    ))}
                  </div>
                </div>
              </section>
            )}

            {sec === "materi" && (
              <section className="section active">
                <PageHead title="Materi" sub="Kelola materi pelajaran untuk siswa" btn="+ Tambah materi" onBtn={openMateri} />
                <div className="panel">
                  <table>
                    <thead><tr><th>Judul materi</th><th>Mata pelajaran</th><th>Kelas</th><th>Tanggal</th><th></th></tr></thead>
                    <tbody>
                      {materi.map((m, i) => (
                        <tr key={i}>
                          <td style={{ fontWeight: 600 }}>{m.judul}</td><td>{m.mapel}</td><td>{m.kelas}</td><td>{m.tanggal}</td>
                          <td><div className="row-actions"><EditBtn onClick={() => editMateri(i)} /><TrashBtn onClick={() => askDelete("materi", i)} /></div></td>
                        </tr>
                      ))}
                      {!materi.length && <EmptyRow cols={5} text="Belum ada materi." />}
                    </tbody>
                  </table>
                </div>
              </section>
            )}

            {sec === "assessment" && (
              <section className="section active">
                <PageHead title="Assessment" sub="Buat kuis atau ulangan harian (pilihan ganda / esai)" btn="+ Buat assessment" onBtn={openAssessment} />
                <div className="panel">
                  <table>
                    <thead><tr><th>Judul</th><th>Mapel</th><th>Kelas</th><th>Tipe</th><th>Jumlah soal</th><th>Total poin</th><th>Waktu</th><th>Tenggat</th><th></th></tr></thead>
                    <tbody>
                      {assessment.map((a, i) => (
                        <tr key={i}>
                          <td style={{ fontWeight: 600 }}>{a.judul}</td><td>{a.mapel}</td><td>{a.kelas}</td><td>{a.tipe}</td>
                          <td>{a.jumlahSoal}</td><td>{a.totalPoin}</td>
                          <td>{a.durasi ? a.durasi + " menit" : "-"}</td>
                          <td>{fmtDeadline(a.deadlineDate, a.deadlineTime)}</td>
                          <td><div className="row-actions"><EditBtn onClick={() => editAssessment(i)} /><TrashBtn onClick={() => askDelete("assessment", i)} /></div></td>
                        </tr>
                      ))}
                      {!assessment.length && <EmptyRow cols={9} text="Belum ada assessment." />}
                    </tbody>
                  </table>
                </div>
              </section>
            )}

            {sec === "tugas" && (
              <section className="section active">
                <PageHead title="Tugas" sub="Berikan tugas ke siswa berupa file PDF atau catatan" btn="+ Tambah tugas" onBtn={openTugas} />
                <div className="panel">
                  <table>
                    <thead><tr><th>Judul tugas</th><th>Mapel</th><th>Kelas</th><th>Jenis</th><th>Tenggat</th><th></th></tr></thead>
                    <tbody>
                      {tugas.map((t, i) => (
                        <tr key={i}>
                          <td style={{ fontWeight: 600 }}>{t.judul}</td><td>{t.mapel}</td><td>{t.kelas}</td><td><Pill s={t.jenis} /></td>
                          <td>{fmtDeadline(t.deadlineDate, t.deadlineTime)}</td>
                          <td><div className="row-actions"><EditBtn onClick={() => editTugas(i)} /><TrashBtn onClick={() => askDelete("tugas", i)} /></div></td>
                        </tr>
                      ))}
                      {!tugas.length && <EmptyRow cols={6} text="Belum ada tugas." />}
                    </tbody>
                  </table>
                </div>
              </section>
            )}

            {sec === "nilai" && (
              <section className="section active">
                <p className="page-title">Nilai</p>
                <p className="page-sub">Masukkan nilai tugas, kuis, dan ulangan harian — nilai akhir terhitung otomatis</p>
                <div className="panel">
                  <div className="panel-head">
                    <h2>XII PPLG 2 - Basis Data</h2>
                    <button className="btn btn-primary" onClick={() => showToast("Nilai berhasil disimpan.")}>Simpan nilai</button>
                  </div>
                  <table>
                    <thead><tr><th>Nama siswa</th><th>Tugas</th><th>Kuis</th><th>Ulangan harian</th><th>Nilai akhir</th></tr></thead>
                    <tbody>
                      {nilai.map((n, i) => (
                        <tr key={n.nis}>
                          <td style={{ fontWeight: 600 }}>{n.nama}</td>
                          {["tugas", "kuis", "uh"].map((f) => (
                            <td key={f}><input className="nilai-input" type="number" min="0" max="100" value={n[f]} onChange={(e) => updateNilai(i, f, e.target.value)} /></td>
                          ))}
                          <td style={{ fontWeight: 700, color: "var(--tosca-700)" }}>{hitungAkhir(n.tugas, n.kuis, n.uh)}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </section>
            )}

            {sec === "pengumuman" && (
              <section className="section active">
                <p className="page-title">Pengumuman</p>
                <p className="page-sub">Status pengumpulan tugas siswa dan himbauan dari admin</p>
                <div className="panel">
                  <div className="panel-head">
                    <h2>Status pengumpulan tugas</h2>
                    <select className="btn" style={{ cursor: "pointer" }} value={activeFilter} onChange={(e) => setFilterTugas(e.target.value)}>
                      {tugas.map((t) => <option key={t.judul} value={t.judul}>{t.judul}</option>)}
                    </select>
                  </div>
                  <table>
                    <thead><tr><th>Nama siswa</th><th>Kelas</th><th>Status</th><th>Waktu kumpul</th></tr></thead>
                    <tbody>
                      {waktuKumpul.map((d) => (
                        <tr key={d.nama}><td style={{ fontWeight: 600 }}>{d.nama}</td><td>{d.kelas}</td><td><Pill s={d.status} /></td><td>{d.waktu}</td></tr>
                      ))}
                      {!waktuKumpul.length && <EmptyRow cols={4} text="Belum ada data." />}
                    </tbody>
                  </table>
                </div>
                <div className="panel">
                  <div className="panel-head"><h2>Himbauan dari admin</h2></div>
                  <div>
                    {adminNotif.map((n) => (
                      <div className="notif-card" key={n.judul}>
                        <div className="notif-dot read" />
                        <div><div className="notif-title">{n.judul}</div><div className="notif-meta">{n.tanggal}</div><div className="notif-body">{n.isi}</div></div>
                      </div>
                    ))}
                  </div>
                </div>
              </section>
            )}

            {sec === "profil" && (
              <section className="section active">
                <p className="page-title">Profil</p>
                <p className="page-sub">Data pribadi kamu</p>
                <div className="profile-card">
                  <div className="profile-avatar">PB</div>
                  {[["Nama lengkap", "Budiono, S.Pd."], ["NIP", "198504122010011005"], ["Mata pelajaran diampu", "Basis Data, Pemrograman Web"], ["Email", "budiono@guru.smkcitranegara.sch.id"], ["No. HP", "0813-7788-9900"]].map(([l, v]) => (
                    <div className="field-row" key={l}><label>{l}</label><input type="text" value={v} readOnly /></div>
                  ))}
                </div>
              </section>
            )}
          </div>
        </div>
      </div>

      {/* Modal materi */}
      <Modal open={modal === "materi"} onClose={close}>
        <h3>{mEdit !== null ? "Edit materi" : "Tambah materi"}</h3>
        <p className="sub">Materi akan langsung tersedia untuk siswa di kelas terkait.</p>
        <Err msg={modal === "materi" && tErr} />
        <div className="field-row"><label>Judul materi</label><input type="text" placeholder="Contoh: Konsep Dasar Basis Data" value={mForm.judul || ""} onChange={(e) => setMForm({ ...mForm, judul: e.target.value })} /></div>
        <div className="field-row-2">
          <div className="field-row"><label>Mata pelajaran</label><select value={mForm.mapel} onChange={(e) => setMForm({ ...mForm, mapel: e.target.value })}><Opts list={MAPEL} /></select></div>
          <div className="field-row"><label>Kelas</label><select value={mForm.kelas} onChange={(e) => setMForm({ ...mForm, kelas: e.target.value })}><Opts list={KELAS} /></select></div>
        </div>
        <div className="field-row"><label>Upload file (opsional)</label><input type="file" accept=".pdf,.ppt,.pptx,.doc,.docx" /></div>
        <div className="field-row"><label>Catatan / ringkasan materi</label><textarea placeholder="Tulis ringkasan materi di sini..." value={mForm.catatan || ""} onChange={(e) => setMForm({ ...mForm, catatan: e.target.value })} /></div>
        <div className="form-actions">
          <button className="btn" onClick={close}>Batal</button>
          <button className="btn btn-primary" onClick={saveMateri}>Simpan</button>
        </div>
      </Modal>

      {/* Modal tugas */}
      <Modal open={modal === "tugas"} onClose={close}>
        <h3>{tEdit !== null ? "Edit tugas" : "Tambah tugas"}</h3>
        <p className="sub">Tugas berupa file PDF atau catatan teks yang harus dikerjakan siswa.</p>
        <Err msg={modal === "tugas" && tErr} />
        <div className="field-row"><label>Judul tugas</label><input type="text" placeholder="Contoh: Membuat ERD Toko Online" value={tForm.judul || ""} onChange={(e) => setTForm({ ...tForm, judul: e.target.value })} /></div>
        <div className="field-row-2">
          <div className="field-row"><label>Mata pelajaran</label><select value={tForm.mapel} onChange={(e) => setTForm({ ...tForm, mapel: e.target.value })}><Opts list={MAPEL} /></select></div>
          <div className="field-row"><label>Kelas</label><select value={tForm.kelas} onChange={(e) => setTForm({ ...tForm, kelas: e.target.value })}><Opts list={KELAS} /></select></div>
        </div>
        <div className="field-row-2">
          <div className="field-row"><label>Batas pengumpulan (tanggal)</label><input type="date" value={tForm.deadlineDate || ""} onChange={(e) => setTForm({ ...tForm, deadlineDate: e.target.value })} /></div>
          <div className="field-row"><label>Batas jam</label><input type="time" value={tForm.deadlineTime || ""} onChange={(e) => setTForm({ ...tForm, deadlineTime: e.target.value })} /></div>
        </div>
        <div className="field-row"><label>Jenis tugas</label>
          <select value={tForm.jenis} onChange={(e) => setTForm({ ...tForm, jenis: e.target.value })}>
            <option value="pdf">Upload file PDF</option>
            <option value="catatan">Catatan teks</option>
          </select>
        </div>
        {tForm.jenis === "pdf" ? (
          <div className="field-row"><label>Upload file PDF</label><input type="file" accept=".pdf" onChange={(e) => setTForm({ ...tForm, fileName: e.target.files[0]?.name || tForm.fileName })} /></div>
        ) : (
          <div className="field-row"><label>Isi catatan tugas</label><textarea placeholder="Tulis instruksi tugas di sini..." value={tForm.catatan || ""} onChange={(e) => setTForm({ ...tForm, catatan: e.target.value })} /></div>
        )}
        <div className="form-actions">
          <button className="btn" onClick={close}>Batal</button>
          <button className="btn btn-primary" onClick={saveTugas}>Simpan</button>
        </div>
      </Modal>

      {/* Modal assessment */}
      <Modal open={modal === "assessment"} onClose={close} style={{ width: 560 }}>
        <h3>{aEdit !== null ? "Edit assessment" : "Buat assessment"}</h3>
        <p className="sub">Tambahkan soal pilihan ganda atau esai, tiap soal punya poin sendiri.</p>
        <Err msg={aErr} />
        <div className="field-row"><label>Judul assessment</label><input type="text" placeholder="Contoh: Kuis Normalisasi Data" value={aForm.judul || ""} onChange={(e) => setAForm({ ...aForm, judul: e.target.value })} /></div>
        <div className="field-row-2">
          <div className="field-row"><label>Mata pelajaran</label><select value={aForm.mapel} onChange={(e) => setAForm({ ...aForm, mapel: e.target.value })}><Opts list={MAPEL} /></select></div>
          <div className="field-row"><label>Kelas</label><select value={aForm.kelas} onChange={(e) => setAForm({ ...aForm, kelas: e.target.value })}><Opts list={KELAS} /></select></div>
        </div>
        <div className="field-row-2">
          <div className="field-row"><label>Tipe</label><select value={aForm.tipe} onChange={(e) => setAForm({ ...aForm, tipe: e.target.value })}><option>Kuis</option><option>Ulangan Harian</option></select></div>
          <div className="field-row"><label>Waktu pengerjaan (menit)</label><input type="number" min="1" max="300" placeholder="Contoh: 30" value={aForm.durasi} onChange={(e) => setAForm({ ...aForm, durasi: e.target.value })} /></div>
        </div>
        <div className="field-row"><label>Tenggat</label><input type="date" value={aForm.deadlineDate || ""} onChange={(e) => setAForm({ ...aForm, deadlineDate: e.target.value })} /></div>

        {soalList.map((s, n) => (
          <div className="soal-card" key={s.id}>
            <div className="soal-card-head">
              <span>Soal {n + 1}</span>
              <TrashBtn title="Hapus soal" onClick={() => setSoalList(soalList.filter((x) => x.id !== s.id))} />
            </div>
            <div className="field-row-2" style={{ marginBottom: 8 }}>
              <div className="field-row" style={{ marginBottom: 0 }}><label>Tipe soal</label>
                <select value={s.tipe} onChange={(e) => setSoal(s.id, { tipe: e.target.value })}><option value="pg">Pilihan Ganda</option><option value="esai">Esai</option></select>
              </div>
              <div className="field-row" style={{ marginBottom: 0 }}><label>Poin</label><input type="number" min="1" value={s.poin} onChange={(e) => setSoal(s.id, { poin: e.target.value })} /></div>
            </div>
            <div className="field-row"><label>Pertanyaan</label><textarea placeholder="Tulis pertanyaan di sini..." style={{ minHeight: 50 }} value={s.tanya} onChange={(e) => setSoal(s.id, { tanya: e.target.value })} /></div>
            {s.tipe === "pg" && (
              <div>
                {s.opsi.map((o, k) => (
                  <div className="opsi-row" key={k}>
                    <input type="radio" name={"benar-" + s.id} checked={s.benar === k} onChange={() => setSoal(s.id, { benar: k })} />
                    <input type="text" placeholder={"Opsi " + "ABCD"[k]} value={o} onChange={(e) => setOpsi(s.id, k, e.target.value)} />
                  </div>
                ))}
                <p style={{ fontSize: 11, color: "var(--ink-soft)", margin: "2px 0 0" }}>Pilih radio di samping opsi jawaban yang benar.</p>
              </div>
            )}
          </div>
        ))}
        <button className="btn" style={{ width: "100%", justifyContent: "center", marginBottom: 14 }} onClick={() => setSoalList([...soalList, blankSoal(nextId(soalList))])}>+ Tambah soal</button>
        <div className="form-actions">
          <button className="btn" onClick={close}>Batal</button>
          <button className="btn btn-primary" onClick={saveAssessment}>Simpan assessment</button>
        </div>
      </Modal>

      {/* Konfirmasi hapus */}
      <Modal open={modal === "confirm"} onClose={close} small>
        <h3>Hapus data ini?</h3>
        <p className="sub">Data yang dihapus tidak bisa dikembalikan.</p>
        <div className="form-actions">
          <button className="btn" onClick={close}>Batal</button>
          <button className="btn btn-primary" style={{ background: "var(--coral)", borderColor: "var(--coral)" }} onClick={confirmDelete}>Ya, hapus</button>
        </div>
      </Modal>

      {/* Logout */}
      <Modal open={modal === "logout"} onClose={close} small>
        <h3>Keluar dari akun?</h3>
        <p className="sub">Kamu akan diarahkan kembali ke halaman login.</p>
        <div className="form-actions">
          <button className="btn" onClick={close}>Batal</button>
          <button className="btn btn-primary" style={{ background: "var(--coral)", borderColor: "var(--coral)" }} onClick={() => setLoggedOut(true)}>Ya, keluar</button>
        </div>
      </Modal>

      <div className={"toast" + (toast ? " show" : "")}>{toast}</div>
    </>
  );
}